def causal_velocity(positions, times, episodes):
    if not (len(positions)==len(times)==len(episodes)):
        raise ValueError('length mismatch')
    result=[]
    for t in range(len(positions)):
        if t==0 or episodes[t]!=episodes[t-1]:
            result.append(None)
        else:
            dt=times[t]-times[t-1]
            if dt<=0:
                raise ValueError('non-increasing time')
            result.append((positions[t]-positions[t-1])/dt)
    return result

