import torch

def reset_hidden(hidden, reset_mask, truncate):
    if hidden.ndim!=3 or reset_mask.shape!=(hidden.shape[1],) or reset_mask.dtype!=torch.bool:
        raise ValueError('invalid hidden or reset mask')
    source=hidden.detach() if truncate else hidden
    return torch.where(reset_mask[None,:,None],torch.zeros_like(source),source)

