import torch

def aggregate_dagger(old_obs,old_actions,visited,teacher):
    if len(old_obs)!=len(old_actions) or old_obs.shape[1:]!=visited.shape[1:]:
        raise ValueError('observation shape mismatch')
    with torch.no_grad():
        new_actions=teacher(visited)
    if new_actions.shape!=(len(visited),*old_actions.shape[1:]):
        raise ValueError('teacher action shape mismatch')
    return torch.cat([old_obs.detach(),visited.detach()]),torch.cat([old_actions.detach(),new_actions.detach()])

