def discounted_returns(rewards,gamma,bootstrap=0.0):
    if not 0<=gamma<=1:
        raise ValueError('gamma outside [0,1]')
    result=[]
    future=float(bootstrap)
    for reward in reversed(rewards):
        future=float(reward)+gamma*future
        result.append(future)
    return result[::-1]

