import torch

def td_targets(reward,next_value,terminated,truncated,gamma):
    if reward.ndim!=1 or any(x.shape!=reward.shape for x in (next_value,terminated,truncated)):
        raise ValueError('shape mismatch')
    if terminated.dtype!=torch.bool or truncated.dtype!=torch.bool or not 0<=gamma<=1:
        raise ValueError('invalid flags or discount')
    # truncated 仅用于外层回合管理，不属于这个 bootstrap mask。
    with torch.no_grad():
        bootstrap = torch.where(terminated, torch.zeros_like(next_value), next_value)
        if not torch.isfinite(reward).all() or not torch.isfinite(bootstrap).all():
            raise ValueError("non-finite valid reward or bootstrap")
        return reward + gamma * bootstrap

