import math

def categorical_logit_gradient(probabilities,chosen,advantage):
    if not probabilities or not 0<=chosen<len(probabilities):
        raise ValueError('invalid action')
    if any(p<0 or not math.isfinite(p) for p in probabilities) or not math.isclose(sum(probabilities),1.0):
        raise ValueError('invalid distribution')
    return [advantage*(p-(1.0 if j==chosen else 0.0)) for j,p in enumerate(probabilities)]

