import torch
from torch.distributions import Normal

def gaussian_actor_loss(mu,log_std,actions,advantages):
    if mu.ndim!=2 or actions.shape!=mu.shape or advantages.shape!=(len(mu),):
        raise ValueError('shape mismatch')
    if log_std.shape not in ((mu.shape[1],),mu.shape):
        raise ValueError('invalid log_std shape')
    std=log_std.clamp(-5.,2.).exp()
    distribution=Normal(mu,std)
    joint_log_prob=distribution.log_prob(actions.detach()).sum(dim=-1)
    return -(joint_log_prob*advantages.detach()).mean()

