import math

def choose_action(plans,now,dt,max_age,epoch):
    if dt<=0 or max_age<0:
        raise ValueError('invalid timing configuration')
    candidates=[]
    for p in plans:
        if p['ready']>now or p['obs']>now or p['epoch']!=epoch or now-p['obs']>max_age:
            continue
        index=math.floor((now-p['start'])/dt+1e-9)
        if 0<=index<len(p['values']):
            candidates.append((p['values'][index],index,p['obs']))
    return max(candidates,key=lambda x:x[2]) if candidates else None

