import torch

def limit_reference(previous,target,dt,max_rate,lower,upper):
    if previous.ndim!=2 or target.shape!=previous.shape or dt<=0:
        raise ValueError('invalid shape or dt')
    if any(v.shape!=(previous.shape[-1],) for v in (max_rate,lower,upper)):
        raise ValueError('invalid bound shape')
    if not all(torch.isfinite(v).all() for v in (previous,target,max_rate,lower,upper)):
        raise ValueError('non-finite input')
    if (max_rate<0).any() or (lower>upper).any():
        raise ValueError('invalid bounds')
    lo=torch.maximum(lower,previous-max_rate*dt)
    hi=torch.minimum(upper,previous+max_rate*dt)
    if (lo>hi).any():
        raise ValueError('empty feasible reference interval')
    return torch.maximum(lo,torch.minimum(hi,target))

