def contract_errors(saved,runtime,train_groups,eval_groups):
    errors=[]
    for key in REQUIRED:
        if key not in saved or key not in runtime:
            errors.append('missing:'+key)
        elif saved[key]!=runtime[key]:
            errors.append('mismatch:'+key)
    if saved.get('causal_history') is not True or runtime.get('causal_history') is not True:
        errors.append('noncausal_history')
    if set(train_groups)&set(eval_groups):
        errors.append('group_overlap')
    return errors

